import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { vi } from "vitest";
import { I18nProvider, ThemeProvider } from "@omnicore-platform/platform-chrome";
import { ComposeBox } from "../../src/components/ComposeBox";

function renderCompose(onSubmit = vi.fn()): { onSubmit: ReturnType<typeof vi.fn> } {
  render(
    <I18nProvider>
      <ThemeProvider>
        <ComposeBox onSubmit={onSubmit} />
      </ThemeProvider>
    </I18nProvider>,
  );
  return { onSubmit };
}

test("disables the Post button when the textarea is empty", () => {
  renderCompose();
  expect(screen.getByRole("button", { name: "Post" })).toBeDisabled();
});

test("enables Post and submits the trimmed body, then clears", async () => {
  const user = userEvent.setup();
  const { onSubmit } = renderCompose();
  const box = screen.getByRole("textbox");
  await user.type(box, "hello world");
  const post = screen.getByRole("button", { name: "Post" });
  expect(post).toBeEnabled();
  await user.click(post);
  expect(onSubmit).toHaveBeenCalledWith("hello world");
  expect(box).toHaveValue("");
});

test("shows remaining-character count and blocks over-limit submit", async () => {
  const user = userEvent.setup();
  const { onSubmit } = renderCompose();
  const box = screen.getByRole("textbox");
  await user.type(box, "x".repeat(281));
  // 280-char limit — over-limit must not submit.
  expect(screen.getByRole("button", { name: "Post" })).toBeDisabled();
  await user.click(screen.getByRole("button", { name: "Post" }));
  expect(onSubmit).not.toHaveBeenCalled();
});


