/**
 * FeedPanel action coverage — reposting a feed post upserts it via
 * feed.replace, and quoting a post prepends the quote to the feed via the
 * QuoteComposer's onPosted callback.
 */

import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { MemoryRouter } from "react-router-dom";
import { afterEach, expect, test } from "vitest";
import { I18nProvider, ThemeProvider } from "@omnicore-platform/platform-chrome";
import {
  ToastHost,
  __resetToasts,
} from "@omnicore-platform/platform-chrome/toast";
import { server } from "../setup";
import { FeedPanel } from "../../src/components/FeedPanel";
import type { KiteSession } from "../../src/api/kite";

afterEach(() => server.resetHandlers());
afterEach(() => __resetToasts());

function feedPost(id: string, body: string): Record<string, unknown> {
  return {
    id,
    org_id: "org-1",
    exercise_id: "ex-1",
    character_id: "c-2",
    parent_post_id: null,
    body,
    is_ai_generated: false,
    is_deleted: false,
    mentions: [],
    created_at: "2026-06-03T11:00:00Z",
    like_count: 0,
    repost_count: 0,
    reply_count: 0,
    quote_count: 0,
    quoted_post_id: "",
    liked: false,
    author_username: "nova",
    author_display_name: "Nova",
    author_avatar_color: "#9B1414",
    faction_color: "",
  };
}

const session: KiteSession = {
  character: {
    id: "char-1",
    handle: "atlas",
    display_name: "Atlas",
    avatar_color: "#2C66EC",
    bio: "",
  },
  exercise: { id: "ex-1", name: "Op Aurora" },
};

function renderFeed(): void {
  render(
    <I18nProvider>
      <ThemeProvider>
        <ToastHost />
        <MemoryRouter initialEntries={["/k/ex-1/home"]}>
          <FeedPanel session={session} />
        </MemoryRouter>
      </ThemeProvider>
    </I18nProvider>,
  );
}

test("renders the error state when the feed fails to load", async () => {
  server.use(
    http.get("/api/v1/kite/exercises/:id/feed", () =>
      HttpResponse.json(
        { error: { code: "internal", message: "feed down" } },
        { status: 500 },
      ),
    ),
  );
  renderFeed();
  // Feed load failure now surfaces via a danger toast (role="alert") plus a
  // quiet in-page role="status" placeholder, rather than an inline alert.
  expect(await screen.findByRole("alert")).toBeInTheDocument();
});

test("renders the empty state when the feed has no posts", async () => {
  server.use(
    http.get("/api/v1/kite/exercises/:id/feed", () =>
      HttpResponse.json({ data: { posts: [], next_page_token: "" } }),
    ),
  );
  renderFeed();
  // The compose box renders, but no PostCard articles do.
  await waitFor(() =>
    expect(screen.queryByRole("status")).not.toBeInTheDocument(),
  );
  expect(screen.queryByRole("article")).not.toBeInTheDocument();
});

test("Load more appends the next page when a cursor is present", async () => {
  server.use(
    http.get("/api/v1/kite/exercises/:id/feed", ({ request }) => {
      const token = new URL(request.url).searchParams.get("page_token");
      if (!token) {
        return HttpResponse.json({
          data: {
            posts: [feedPost("p-1", "page one post")],
            next_page_token: "cursor-1",
          },
        });
      }
      return HttpResponse.json({
        data: {
          posts: [feedPost("p-2", "page two post")],
          next_page_token: "",
        },
      });
    }),
  );
  const user = userEvent.setup();
  renderFeed();
  await screen.findByText("page one post");
  await user.click(screen.getByRole("button", { name: "Show more" }));
  expect(await screen.findByText("page two post")).toBeInTheDocument();
});

test("reposting a feed post upserts it in place", async () => {
  const user = userEvent.setup();
  renderFeed();

  const card = (await screen.findByText("First post in the feed"))
    .closest("article") as HTMLElement;
  await user.click(within(card).getByRole("button", { name: /Repost/ }));
  await user.click(await screen.findByRole("menuitem", { name: /^Repost/ }));

  // The mutation resolves; the post remains in the feed.
  await waitFor(() =>
    expect(screen.getByText("First post in the feed")).toBeInTheDocument(),
  );
});

test("switching to Following and back to For you re-selects the For-you tab", async () => {
  const user = userEvent.setup();
  renderFeed();
  await screen.findByText("First post in the feed");

  const following = screen.getByRole("tab", { name: "Following" });
  await user.click(following);
  await waitFor(() =>
    expect(following).toHaveAttribute("aria-selected", "true"),
  );

  const forYou = screen.getByRole("tab", { name: "For you" });
  await user.click(forYou);
  await waitFor(() =>
    expect(forYou).toHaveAttribute("aria-selected", "true"),
  );
});

test("quoting a feed post prepends the quote to the feed", async () => {
  const user = userEvent.setup();
  renderFeed();

  const card = (await screen.findByText("First post in the feed"))
    .closest("article") as HTMLElement;
  await user.click(within(card).getByRole("button", { name: /Repost/ }));
  await user.click(await screen.findByRole("menuitem", { name: /Quote/ }));

  const dialog = await screen.findByRole("dialog");
  await user.type(within(dialog).getByRole("textbox"), "my hot take");
  await user.click(within(dialog).getByRole("button", { name: "Post" }));

  // The quote (q-new from the default :quote handler) is prepended to the feed.
  expect(await screen.findByText("my hot take")).toBeInTheDocument();
});


