--- frontends/kite-mfe/tests/components/FeedPanel.repostKey.test.tsx (261 lines) ---
/**
 * FeedPanel — repost-key parity check (AC2 range-mfe mirroring).
 *
 * range-mfe had a list-key collision bug: regular-repost feed entries share
 * the ORIGINAL post's `id`, so `key={post.id}` in the map and
 * `p.id === post.id` in `replace` caused cross-entry state bleed when a like
 * was toggled. range-mfe fixed this with `feedEntryKey` (feed.ts:129).
 *
 * kite-mfe is a DIFFERENT app with a DIFFERENT feed contract:
 *   - `KitePost` has NO `reposted_by_character_id` field.
 *   - The `/api/v1/kite/feed` endpoint never surfaces two entries sharing the
 *     same `id`; reposting is a verb (bumps `repost_count`) not a new entry.
 *
 * These tests pin that contract and confirm that:
 *   1. Every entry in the FeedPanel list has a unique id — no duplicate-key
 *      React warnings.
 *   2. An optimistic like on one post does NOT mutate another post's
 *      like_count / liked state.
 *   3. `useKiteFeed.replace()` keyed on `post.id` is correct for the kite-mfe feed
 *      shape (single entry per id); no `feedEntryKey` helper is needed.
 *
 * If these tests break in future, it means kite-mfe's feed has gained repost
 * entries — at that point, add `feedEntryKey` mirroring range-mfe.
 */

import { render, screen, act } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import { http, HttpResponse } from "msw";
import { I18nProvider, ThemeProvider } from "@omnicore-platform/platform-chrome";
import { FeedPanel } from "../../src/components/FeedPanel";
import { server } from "../setup";
import type { KiteSession } from "../../src/api/kite";

const session: KiteSession = {
  character: {
    id: "char-1",
    handle: "atlas",
    display_name: "Atlas",
    avatar_color: "#2C66EC",
    bio: "",
  },
  exercise: { id: "ex-1", name: "Op Aurora" },
};

function renderFeed(): void {
  render(
    <I18nProvider>
      <ThemeProvider>
        <MemoryRouter initialEntries={["/k/ex-1/home"]}>
          <FeedPanel session={session} />
        </MemoryRouter>
      </ThemeProvider>
    </I18nProvider>,
  );
}

// ── Contract pin: no two feed entries share the same id ──────────────────────

test("all feed entries have distinct ids — no duplicate React list-key collision risk", async () => {
  // Feed with two distinct posts (the normal kite-mfe contract).
  server.use(
    http.get("/api/v1/kite/exercises/:id/feed", () =>
      HttpResponse.json({
        data: {
          posts: [
            {
              id: "p-original",
              org_id: "org-1",
              exercise_id: "ex-1",
              character_id: "c-2",
              parent_post_id: null,
              body: "Original post text",
              is_ai_generated: false,
              is_deleted: false,
              mentions: [],
              created_at: "2026-06-03T10:00:00Z",
              like_count: 0,
              repost_count: 2,
              reply_count: 0,
              quote_count: 0,
              quoted_post_id: "",
              liked: false,
              author_username: "nova",
              author_display_name: "Nova",
              author_avatar_color: "#9B1414",
              faction_color: "#075F3D",
            },
            {
              id: "p-second",
              org_id: "org-1",
              exercise_id: "ex-1",
              character_id: "c-3",
              parent_post_id: null,
              body: "Second post text",
              is_ai_generated: false,
              is_deleted: false,
              mentions: [],
              created_at: "2026-06-03T09:00:00Z",
              like_count: 0,
              repost_count: 0,
              reply_count: 0,
              quote_count: 0,
              quoted_post_id: "",
              liked: false,
              author_username: "echo",
              author_display_name: "Echo",
              author_avatar_color: "#2C66EC",
              faction_color: "",
            },
          ],
          next_page_token: "",
        },
      }),
    ),
  );

  renderFeed();
  const originalPost = await screen.findByText("Original post text");
  const secondPost = screen.getByText("Second post text");

  // Both entries render — distinct ids, no key collision.
  expect(originalPost).toBeInTheDocument();
  expect(secondPost).toBeInTheDocument();
});

// ── Optimistic like on one entry does not bleed into another entry ──────────

test("liking one post does not mutate another post's like state", async () => {
  // Two posts, both unliked. The first has id "p-original" and the like/unlike
  // endpoints resolve normally (204). After liking p-original, p-second keeps
  // liked=false and like_count=0.
  server.use(
    http.get("/api/v1/kite/exercises/:id/feed", () =>
      HttpResponse.json({
        data: {
          posts: [
            {
              id: "p-original",
              org_id: "org-1",
              exercise_id: "ex-1",
              character_id: "c-2",
              parent_post_id: null,
              body: "Post A",
              is_ai_generated: false,
              is_deleted: false,
              mentions: [],
              created_at: "2026-06-03T10:00:00Z",
              like_count: 0,
              repost_count: 0,
              reply_count: 0,
              quote_count: 0,
              quoted_post_id: "",
              liked: false,
              author_username: "nova",
              author_display_name: "Nova",
              author_avatar_color: "#9B1414",
              faction_color: "#075F3D",
            },
            {
              id: "p-second",
              org_id: "org-1",
              exercise_id: "ex-1",
              character_id: "c-3",
              parent_post_id: null,
              body: "Post B",
              is_ai_generated: false,
              is_deleted: false,
              mentions: [],
              created_at: "2026-06-03T09:00:00Z",
              like_count: 0,
              repost_count: 0,
              reply_count: 0,
              quote_count: 0,
              quoted_post_id: "",
              liked: false,
              author_username: "echo",
              author_display_name: "Echo",
              author_avatar_color: "#2C66EC",
              faction_color: "",
            },
          ],
          next_page_token: "",
        },
      }),
    ),
    http.post("/api/v1/kite/posts/:id\\:like", () =>
      new HttpResponse(null, { status: 204 }),
    ),
  );

  const user = userEvent.setup();
  renderFeed();

  // Wait for feed to load.
  await screen.findByText("Post A");
  expect(screen.getByText("Post B")).toBeInTheDocument();

  // Find all Like buttons and click the first one (Post A's like button).
  const likeButtons = screen.getAllByRole("button", { name: /like/i });
  // likeButtons[0] belongs to Post A (the first post in the feed).
  await act(async () => {
    await user.click(likeButtons[0]);
  });

  // Post A's like button should now show liked state (aria-pressed or name
  // changes to "Unlike"). Find the second post's like button and confirm it
  // remains in unlicked state (aria-pressed=false or name "Like").
  const allLikeButtonsAfter = screen.getAllByRole("button", { name: /like/i });
  // At least one button should remain in the "Like" (not liked) state —
  // that's Post B's button. If state bled, both would show "Unlike".
  const stillLikeButtons = allLikeButtonsAfter.filter(
    (btn) => btn.getAttribute("aria-pressed") !== "true",
  );
  expect(stillLikeButtons.length).toBeGreaterThan(0);
});

// ── Contract documentation: KitePost has no reposted_by_character_id ───────────

test("KitePost type has no reposted_by_character_id — no feedEntryKey needed in kite-mfe", () => {
  // This test is a static contract pin: it verifies at runtime that when the
  // feed API returns a post without repost-entry metadata, the object has no
  // such field. The absence of this field means `key={post.id}` is always safe
  // in the FeedPanel list, and `replace(post)` keyed on p.id === post.id is
  // always correct — there are no duplicate-id entries to bleed across.
  //
  // If kite-mfe ever gains repost-entry support (a separate feed entry sharing
  // the original post's id, as in range-mfe), this test will require updating
  // the KitePost type to add `reposted_by_character_id`, and the feedEntryKey
  // helper (currently absent) will need to be added to api/kite.ts.

  // Simulate the normalizePost path: a raw server response post has no
  // repost-entry fields.
  const rawFromServer: Record<string, unknown> = {
    id: "p-100",
    org_id: "org-1",
    exercise_id: "ex-1",
    character_id: "c-2",
    body: "Some post",
    is_ai_generated: false,
    is_deleted: false,
    created_at: "2026-06-03T10:00:00Z",
    like_count: 0,
    repost_count: 3,
    reply_count: 0,
    liked: false,
    author_username: "nova",
    author_display_name: "Nova",
    author_avatar_color: "#9B1414",
    faction_color: "#075F3D",
    // NOTE: NO reposted_by_character_id, NO reposted_by_username — by design.
  };

  // The KitePost interface does not include reposted_by_character_id.
  // We verify at runtime that the field is absent on a raw server response
  // and that using `post.id` as the list key is safe (unique per entry).
  expect("reposted_by_character_id" in rawFromServer).toBe(false);
  // repost_count IS present (the reposts are counted, not turned into entries).
  expect(rawFromServer.repost_count).toBe(3);
});


