import { render } from "@testing-library/react";
import { KiteAvatarStyleProvider } from "@omnicore-platform/platform-chrome/kite";
import { Avatar } from "../../src/components/Avatar";

/**
 * Avatar (kite-mfe) — now re-points at the shared KiteAvatar (#1900): a
 * non-empty seed renders a real DiceBear <img>, re-styling with an
 * ambient KiteAvatarStyleProvider; an empty seed still falls back to the
 * neutral monogram badge unchanged. See tests/api/kite.test.ts and
 * tests/KiteApp.avatarStyle.test.tsx for the session-wired regression this
 * exists to support.
 */

function img(container: HTMLElement): HTMLImageElement | null {
  return container.querySelector("img");
}

function bgColor(container: HTMLElement): string {
  const span = container.querySelector("span");
  if (span === null) throw new Error("avatar span not found");
  return (span as HTMLElement).style.backgroundColor;
}

test("a non-empty seed renders a DiceBear <img>, not the monogram span", () => {
  const { container } = render(<Avatar displayName="Nova" seed="char-1" />);
  const el = img(container);
  expect(el).not.toBeNull();
  expect(el?.getAttribute("src")).toMatch(/^data:image\/svg\+xml/);
  expect(container.querySelector("span")).not.toBeInTheDocument();
});

test("the same seed yields the same rendered src", () => {
  const a = render(<Avatar displayName="Nova" seed="char-1" />);
  const b = render(<Avatar displayName="Different Name" seed="char-1" />);
  expect(img(a.container)?.getAttribute("src")).toBe(
    img(b.container)?.getAttribute("src"),
  );
});

test("different seeds generally yield different rendered src", () => {
  const sources = new Set(
    Array.from({ length: 12 }, (_, i) => {
      const { container } = render(<Avatar displayName="X" seed={`char-${i}`} />);
      return img(container)?.getAttribute("src");
    }),
  );
  expect(sources.size).toBeGreaterThan(1);
});

test("an empty seed falls back to the neutral monogram badge (no <img>)", () => {
  const { container } = render(<Avatar displayName="Nova" seed="" />);
  expect(img(container)).toBeNull();
  expect(bgColor(container)).not.toBe("");
});

test("re-styles with the ambient KiteAvatarStyleProvider", () => {
  const disco = render(
    <KiteAvatarStyleProvider style="disco">
      <Avatar displayName="Nova" seed="char-1" />
    </KiteAvatarStyleProvider>,
  );
  const lorelei = render(
    <KiteAvatarStyleProvider style="lorelei">
      <Avatar displayName="Nova" seed="char-1" />
    </KiteAvatarStyleProvider>,
  );
  expect(img(disco.container)?.getAttribute("src")).not.toBe(
    img(lorelei.container)?.getAttribute("src"),
  );
});


