/**
 * KiteLayout coverage — the kite-mfe adapter owns the session-coupled logout flow:
 * clicking Log out calls logout(), clears the cached session, and navigates to
 * /k/login. Even when the server logout call fails, the participant is still
 * bounced to login (never stranded half-authed).
 */

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { afterEach, expect, test } from "vitest";
import { I18nProvider, ThemeProvider } from "@omnicore-platform/platform-chrome";
import {
  ToastHost,
  __resetToasts,
} from "@omnicore-platform/platform-chrome/toast";
import { server } from "../setup";
import { KiteLayout } from "../../src/components/KiteLayout";
import type { KiteSession } from "../../src/api/kite";

afterEach(() => {
  server.resetHandlers();
  __resetToasts();
});

const session: KiteSession = {
  character: {
    id: "char-1",
    handle: "atlas",
    display_name: "Atlas",
    avatar_color: "#2C66EC",
    bio: "",
  },
  exercise: { id: "ex-1", name: "Op Aurora" },
};

const CHILD = "child content";
const LOGIN_MARKER = "login-screen";

function renderLayout(): void {
  render(
    <I18nProvider>
      <ThemeProvider>
        <ToastHost />
        <MemoryRouter initialEntries={["/k/ex-1/home"]}>
          <Routes>
            <Route
              path="/k/:exercise/home"
              element={
                <KiteLayout session={session}>
                  <p>{CHILD}</p>
                </KiteLayout>
              }
            />
            <Route path="/k/login" element={<p>{LOGIN_MARKER}</p>} />
          </Routes>
        </MemoryRouter>
      </ThemeProvider>
    </I18nProvider>,
  );
}

test("renders the children inside the shared shell", () => {
  renderLayout();
  expect(screen.getByText(CHILD)).toBeInTheDocument();
  expect(screen.getByRole("navigation")).toBeInTheDocument();
});

test("Log out clears the session and navigates to /k/login", async () => {
  const user = userEvent.setup();
  server.use(
    http.post(
      "/api/v1/kite/logout",
      () => new HttpResponse(null, { status: 204 }),
    ),
  );
  renderLayout();
  await user.click(screen.getByRole("button", { name: "Log out" }));
  await waitFor(() =>
    expect(screen.getByText(LOGIN_MARKER)).toBeInTheDocument(),
  );
});

test("still navigates to /k/login and shows a danger toast when the server logout call fails", async () => {
  const user = userEvent.setup();
  server.use(
    http.post(
      "/api/v1/kite/logout",
      () => new HttpResponse(null, { status: 500 }),
    ),
