test("the profile link routes by @handle (author_username)", () => {
  renderCard();
  // Both the avatar and the display-name link point at the by-handle profile
  // route — the shareable, human-readable URL key.
  const links = screen.getAllByRole("link", { name: "Atlas" });
  for (const link of links) {
    expect(link).toHaveAttribute("href", "/k/ex-1/profile/atlas");
  }
