});

test("the avatar color is NOT derived from author_avatar_color (no faction leak)", () => {
  // Two posts with the SAME character_id but DIFFERENT author_avatar_color
  // must render the SAME avatar background (color comes from the id seed, not
  // the faction-assigned avatar_color).
  const { container: a } = render(
    <I18nProvider>
      <ThemeProvider>
        <MemoryRouter>
          <PostCard
            post={{ ...post, character_id: "c-77", author_avatar_color: "#9B1414" }}
            exerciseId="ex-1"
            onLikeToggle={() => {}}
            onRepost={() => {}}
            onQuote={() => {}}
          />
        </MemoryRouter>
      </ThemeProvider>
    </I18nProvider>,
  );
  const { container: b } = render(
    <I18nProvider>
      <ThemeProvider>
        <MemoryRouter>
          <PostCard
            post={{ ...post, character_id: "c-77", author_avatar_color: "#075F3D" }}
            exerciseId="ex-1"
            onLikeToggle={() => {}}
            onRepost={() => {}}
            onQuote={() => {}}
          />
        </MemoryRouter>
      </ThemeProvider>
    </I18nProvider>,
  );
  const bgA = (a.querySelector("span") as HTMLElement).style.backgroundColor;
  const bgB = (b.querySelector("span") as HTMLElement).style.backgroundColor;
  expect(bgA).toBe(bgB);
  // And it is not literally the faction-assigned avatar_color.
  expect(bgA).not.toBe("rgb(155, 20, 20)"); // #9B1414
});

test("an outlet auto-post links to its source article at an ABSOLUTE /range URL", () => {
  // kite-mfe is served at /k/* and its router cannot reach the gated shell's
  // /range/* routes, so this href must be absolute — a relative path would
  // resolve inside kite-mfe's own router and 404.
  renderCard({ ...post, source_baseline_article_id: "art-9" });
  expect(
    screen.getByRole("link", { name: m.range_kite_view_article_in_range() }),
  ).toHaveAttribute(
    "href",
    `${window.location.origin}/range/exercises/ex-1/baseline/articles/art-9`,
  );
});

